import{z as s,x as i,o as A,c as D,q as l,j as t,D as a,d as r,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"弱到强闭环","description":"","frontmatter":{"title":"弱到强闭环","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/weak-to-strong-closure.md","filePath":"llm/weak-to-strong-closure.md","lastUpdated":1791413859000}'),d={name:"llm/weak-to-strong-closure.md"};function m(p,E,C,h,F,u){const B=i("Mermaid");return A(),D("div",null,[E[2]||(E[2]=l('<h1 id="弱到强闭环" tabindex="-1">弱到强闭环 <a class="header-anchor" href="#弱到强闭环" aria-label="Permalink to &quot;弱到强闭环&quot;">​</a></h1><div class="epigraph"><p>监督不必与被监督者一样强，但奖励里的错误不会自动蒸发；弱到强泛化赌的是强模型先验里存着正确答案的影子。</p><footer>—— Burns 等, Weak-to-Strong Generalization（2023）</footer></div><p><a href="/llm/self-reward-debate">上一课</a>的结论是循环依赖需要外生锚，但锚不一定要与选手同样强。Burns 等人 2023 年问：弱得多的监督者给强模型提供标签或奖励，强模型能不能超过监督者？这对自训练闭环是根本问题：回路里的监督者通常是上一轮的自己或同族小模型，天然弱于策略的全部潜力。本课写弱到强泛化成立的条件、它失败时的退化对齐，以及它如何收窄上一课的裁判困境——外生性不足时，监督强度问题不会消失，只会换形状。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>naive 做法直接成立吗？Burns 等人的主实验：GPT-2 级弱模型微调成标注器或奖励器，学生是 GPT-4 级预训练模型。若学生只模仿标签，上限就是弱者水平——把强模型对齐到弱者的错误上。实测学生确实超过监督者，但距强监督上限的差距很大；加一个辅助置信损失（让学生与弱者的置信结构对齐，防止过度自信地复制标签）能收回其中一部分。为什么是这样：泛化来自学生预训练先验里已经存在的潜概念，弱标签只负责指认方向。不这么做会错在哪：把「超过弱监督者」读成「对齐成功」，会漏掉学生仍大量继承标签偏差的事实。</p><p><span class="marginnote">术语翻译：弱到强泛化就是「用差老师带出好学生」。弱监督者只保证给方向大致正确的标签（还会时常标错），强学生靠预训练时已经建立的判断力把这些噪声标签「翻译」回正确概念——最终水平超过老师，但天花板仍受标签质量限制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把学生误差拆成两项：\\(\\mathrm{err}=\\mathrm{err}_{\\mathrm{label}}+\\mathrm{err}_{\\mathrm{gen}}\\)。第一项是弱标签的系统性偏差，照抄就继承；第二项是学生从先验恢复潜概念自身的估计误差。弱到强泛化发生，当第二项的下降快于第一项被吸收；退化对齐发生，当学生把标签噪声当成要学的信号。闭环版本是把学生变成下一轮监督者：每轮的奖励质量取决于上一轮学生，没有外生校准时两类误差一起滚。可验证奖励是极限情形——<a href="/llm/rlvr">RLVR</a> 的程序真值与监督者智力无关，监督强度问题在可验证域直接消失；不可验证域则必须报告弱监督与强监督两条曲线的差距，把它当残余风险。</p>',8)),(A(),t(o,null,{default:a(()=>[n(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20WEAK%5B%22%E5%BC%B1%E7%9B%91%E7%9D%A3%E8%80%85%EF%BC%9A%E6%A0%87%E6%B3%A8%20%2F%20%E5%A5%96%E5%8A%B1%22%5D%20--%3E%20LAB%5B%22%E5%B8%A6%E5%81%8F%E5%B7%AE%E7%9A%84%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20LAB%20--%3E%20STU%5B%22%E5%BC%BA%E5%AD%A6%E7%94%9F%E6%9B%B4%E6%96%B0%22%5D%0A%20%20PRIOR%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%E5%85%88%E9%AA%8C%22%5D%20--%3E%20GEN%5B%22%E6%81%A2%E5%A4%8D%E6%BD%9C%E6%A6%82%E5%BF%B5%EF%BC%9Aerr_gen%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20GEN%20--%3E%20STU%0A%20%20STU%20--%3E%20Q%7B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E8%B0%81%E7%9B%91%E7%9D%A3%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%AD%A6%E7%94%9F%E5%BD%93%E7%9B%91%E7%9D%A3%E8%80%85%20%2B%20%E5%A4%96%E7%94%9F%E6%A0%A1%E5%87%86%22%7C%20LOOP%5B%22%E8%AF%AF%E5%B7%AE%E5%8F%97%E6%8E%A7%E7%9A%84%E9%97%AD%E7%8E%AF%22%5D%0A%20%20Q%20--%3E%7C%22%E5%AD%A6%E7%94%9F%E5%BD%93%E7%9B%91%E7%9D%A3%E8%80%85%EF%BC%8C%E6%97%A0%E6%A0%A1%E5%87%86%22%7C%20DEG%5B%22%E9%80%80%E5%8C%96%E5%AF%B9%E9%BD%90%EF%BC%9A%E5%81%8F%E5%B7%AE%E9%80%90%E8%BD%AE%E5%9B%BA%E5%8C%96%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"为什么能超过？潜概念在表示里已经线性可读时，带噪声的弱标签仍够学生把它恢复出来——先验提供容量，弱监督只提供选择。失败模式同样清楚：标签错误若与表面特征相关（长答案对、权威语气对），学生学到的恰是这些特征。退化对齐不是「没学」，是把监督者的偏见学得更瓷实：它同时解释了弱到强的上限与上一课循环依赖的成因——self-rewarding 正是弱到强退化为自我模仿的特例，监督者与策略同分布时 \\(\\mathrm{err}_{\\mathrm{label}}\\) 完全由策略自己的口味构成。锚越外生，标签偏差越不受被优化对象影响，这是两条课共享的结构结论。",-1)),E[5]||(E[5]=e("p",null,"泛化还是退化，取决于标签错误长在哪：错误若随机、与内容无关，学生的先验可以把它「平均掉」；错误若与表面特征绑定，先验无从分辨特征与概念，照单全收。",-1)),(A(),t(o,null,{default:a(()=>[n(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOISE%7B%22%E5%BC%B1%E6%A0%87%E7%AD%BE%E7%9A%84%E9%94%99%E8%AF%AF%E4%B8%8E%E4%BB%80%E4%B9%88%E7%9B%B8%E5%85%B3%22%7D%0A%20%20NOISE%20--%3E%7C%22%E4%B8%8E%E5%86%85%E5%AE%B9%E6%97%A0%E5%85%B3%E7%9A%84%E9%9A%8F%E6%9C%BA%E9%94%99%22%7C%20AVG%5B%22%E5%85%88%E9%AA%8C%E5%B9%B3%E5%9D%87%E6%8E%89%E5%99%AA%E5%A3%B0%22%5D%0A%20%20AVG%20--%3E%20GEN%5B%22%E6%81%A2%E5%A4%8D%E6%BD%9C%E6%A6%82%E5%BF%B5%3A%20err_label%20%E6%9C%89%E7%95%8C%22%5D%0A%20%20NOISE%20--%3E%7C%22%E7%BB%91%E5%AE%9A%E8%A1%A8%E9%9D%A2%E7%89%B9%E5%BE%81%22%7C%20CUE%5B%22%E9%95%BF%E7%AD%94%E6%A1%88%20%2F%20%E6%9D%83%E5%A8%81%E8%AF%AD%E6%B0%94%E8%A2%AB%E5%BD%93%E6%88%90%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20CUE%20--%3E%20DEG%5B%22%E5%AD%A6%E7%94%9F%E5%AD%A6%E4%BC%9A%E5%81%8F%E8%A7%81%3A%20%E9%80%80%E5%8C%96%E5%AF%B9%E9%BD%90%22%5D%0A%20%20GEN%20--%3E%20OK%5B%22%E8%B6%85%E8%BF%87%E5%BC%B1%E7%9B%91%E7%9D%A3%E8%80%85%22%5D%0A%20%20DEG%20--%3E%20BAD%5B%22%E4%B8%8A%E9%99%90%20%3D%20%E5%BC%B1%E8%80%85%E7%9A%84%E5%81%8F%E8%A7%81%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">直觉类比：一位只懂基本规则的下棋爱好者给职业棋手摆参考谱——偶尔摆错一步，棋手凭棋感仍能下得比爱好者高明（泛化）；但如果爱好者的错误有规律，比如「总把车摆在边上」，而棋手被要求严格照谱走，那棋手就会把这毛病学得比爱好者还标准（退化对齐）。区别全在错误是「噪声」还是「伪规律」。</span></p><p><span class="marginnote">Burns 等的弱监督者是 GPT-2 级模型微调出的标注/奖励器，学生是 GPT-4 预训练模型；naive 弱监督的学生已能超过监督者（分类基准上差距可观），但距强监督上限仍远，辅助置信损失在部分任务上收回可观一截差距。这不是「弱监督免费」，是「强先验垫底」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>实验都在学生先验充足的 NLP 任务上；对长程智能体行为、学生也没见过的前沿能力，弱到强没有同等证据，辅助损失也不是通用解。方向不要与蒸馏混淆：<a href="/llm/reasoning-distill-small">推理蒸馏到小模型</a>是强教师训弱学生，这里反过来——弱标签训强学生，学的是超越标签的潜概念，不是模仿教师分布。弱到强更不是替罪羊：「监督不了所以随便给奖励」只会制造退化对齐；诚实做法是把弱监督上限当公开的已知缺口，而不是宣布泛化已经替你解决。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>弱监督者能激发强模型，但 naive 情形离强监督上限很远。</li><li>学生误差 = 弱标签偏差 + 先验恢复误差；退化对齐即前者压过后者。</li><li>闭环里学生当下一轮监督者，误差逐轮复合，需外生校准。</li><li>可验证域里监督强度问题消失；不可验证域必须报告残余差距。</li><li>出处：Burns 等 Weak-to-Strong Generalization（2023）；对照强教师训弱学生的方向见 <a href="/llm/reasoning-distill-small">推理蒸馏到小模型</a>。</li></ul>',6))])}const T=s(d,[["render",m]]);export{f as __pageData,T as default};
